<template>
  <div class="pc-container" :class="{'pc-opening-still':!animationsEnabled}">
  <div :inert="detailOpen?'':null" :aria-hidden="detailOpen?'true':null" class="pc-backdrop" @click.self="close" @keydown="keydown">
    <section ref="dialog" class="pc-terminal" @pointermove="dragMove" @pointerup="dragFinish" @pointercancel="cancelDrag" @lostpointercapture="dragCaptureLost" @pointerleave="dragLeave" @dragstart.prevent role="dialog" aria-modal="true" aria-labelledby="pc-title" :aria-busy="busy || opening">
      <header class="pc-header"><div class="pc-mark" aria-hidden="true"><svg viewBox="0 0 40 40" fill="none" stroke="currentColor" stroke-width="2"><rect x="4" y="5" width="32" height="23" rx="3"/><path d="M15 28v6m10-6v6M10 35h20M20 10v13m-6-6h12"/></svg></div><div><small>CENTRE POKÉMON / {{ state.expedition?'EXPÉDITION':'AVENTURE' }}</small><h2 id="pc-title">Le PC de {{ username || 'ton équipe' }}</h2></div><button ref="close" class="pc-close" aria-label="Fermer le PC" :disabled="busy" @click="close">×</button></header>
      <p :aria-hidden="opening?'true':null" class="pc-feedback" :class="{'pc-feedback-error':error}" :role="error?'alert':'status'" aria-live="polite">{{ error || (drag ? 'Dépose sur une case. Maintiens sur ‹ / › pour changer de boîte.' : notice) || 'Fais glisser un Pokémon, ou sélectionne-le pour voir ses actions.' }}</p>
      <div class="pc-body" :class="{'is-pc-loading':opening}" :inert="opening?'':null" :aria-hidden="opening?'true':null">
        <aside class="pc-party" aria-labelledby="pc-team-title"><div class="pc-section-title"><h3 id="pc-team-title">Ton équipe</h3><span>{{ state.team.length }} / 6</span></div><div class="pc-team-slots"><button v-for="(p,index) in state.team" :key="p.uuid" class="pc-team-member" :class="{selected:selected?.uuid===p.uuid,'pc-drag-source':drag?.pokemon.uuid===p.uuid,'pc-drop-target':dropTarget('team',index)}" :data-pc-team="p.uuid" data-pc-drop="team" :data-pc-index="index" :data-pc-target-uuid="p.uuid" @pointerdown="startDrag($event,p,{kind:'team',index})" :aria-pressed="selected?.uuid===p.uuid" :disabled="busy" @click="select(p,'team')"><span class="pc-party-number">{{ index+1 }}</span><computer-pokemon-portrait :pokemon="p" :src="sprite(p)"/><span class="pc-party-name"><strong>{{ p.name }}</strong><small>Niv. {{ p.level }}<span class="pc-party-health"> · {{ p.currentHp>0?`${p.currentHp}/${p.maxHp} PV`:'K.O.' }}</span></small></span></button><button v-if="state.team.length<6" class="pc-team-empty" data-pc-drop="team" :data-pc-index="state.team.length" :class="{'pc-drop-target':dropTarget('team',state.team.length)}" :disabled="busy" aria-label="Place libre dans l’équipe"><span aria-hidden="true">＋</span><small>Ajouter à l’équipe</small></button></div></aside>
        <main class="pc-box"><div class="pc-box-toolbar"><button aria-label="Boîte précédente" data-pc-box-step="-1" :disabled="busy" @click="changeBox((box+state.boxCount-1)%state.boxCount)">‹</button><label class="pc-box-label"><span>STOCKAGE</span><select aria-label="Choisir une boîte" :value="box" :disabled="busy" @change="changeBox(Number($event.target.value))"><option v-for="n in state.boxCount" :key="n" :value="n-1">Boîte {{ n }} · {{ boxCount(n-1) }} / {{ state.boxSize }}</option></select></label><button aria-label="Boîte suivante" data-pc-box-step="1" :disabled="busy" @click="changeBox((box+1)%state.boxCount)">›</button></div>
          <div class="pc-grid" role="group" :aria-label="`Pokémon de la Boîte ${box+1}`"><button v-for="(entry,index) in slots" :key="index" class="pc-box-slot" :class="{occupied:entry,selected:entry && selected?.uuid===entry.pokemon.uuid,'pc-drag-source':entry && drag?.pokemon.uuid===entry.pokemon.uuid,'pc-drop-target':dropTarget('box',index)}" :disabled="busy" :tabindex="entry?0:-1" :data-pc-slot="index" data-pc-drop="box" :data-pc-box="box" :data-pc-target-uuid="entry?.pokemon.uuid" @pointerdown="entry && startDrag($event,entry.pokemon,{kind:'box',box,slot:index})" :data-pc-pokemon="entry?.pokemon.uuid" :aria-pressed="Boolean(entry && selected?.uuid===entry.pokemon.uuid)" :aria-label="entry?`${entry.pokemon.name}, niveau ${entry.pokemon.level}, potentiel K${entry.pokemon.potential}${entry.pokemon.heldItem?`, objet ${entry.pokemon.heldItemName || entry.pokemon.heldItem}`:''}`:`Emplacement ${index+1} vide`" @click="entry && select(entry.pokemon,'box')"><computer-pokemon-portrait v-if="entry" :pokemon="entry.pokemon" :src="sprite(entry.pokemon)"/><small v-if="entry">{{ entry.pokemon.level }}</small><span v-else aria-hidden="true">·</span></button></div>
          <p class="pc-grid-help">Glisse vers une case libre pour déplacer, ou vers un Pokémon pour échanger. Les marges restent disponibles pour faire défiler.</p>
        </main>
        <aside ref="details" class="pc-details" aria-label="Pokémon sélectionné">
          <template v-if="selected"><div class="pc-selected-heading"><pokemon-portrait :src="sprite(selected)"/><div><small>{{ source==='team'?'DANS TON ÉQUIPE':`BOÎTE ${box+1}` }}</small><h3>{{ selected.name }}</h3><span>Niv. {{ selected.level }}</span> <potential-star :value="selected.potential"/></div></div><div class="pc-types"><span v-for="type in selected.types" :key="type">{{ typeName(type) }}</span></div><p class="pc-hp">{{ selected.currentHp>0?`${selected.currentHp} / ${selected.maxHp} PV`:'K.O.' }} <small v-if="selected.status && selected.status!=='normal'">· {{ selected.status }}</small></p><dl class="pc-traits"><div><dt>Talent</dt><dd>{{ abilityName(selected.passiveAbility) || 'Aucun' }}</dd></div><div><dt>Objet tenu</dt><dd>{{ selected.heldItemName || itemName(selected.heldItem) }}</dd></div></dl><p class="pc-moves">{{ selected.moves.map(m=>moveName(m)).join(' · ') }}</p>
            <div class="pc-actions"><button ref="detailButton" class="pc-show-details" data-pc-details :disabled="busy" @click="openDetail">Voir la fiche complète</button><template v-if="source==='team'"><button class="pc-primary" data-pc-deposit :disabled="busy || !canRemove || boxCount(box)>=state.boxSize" @click="send('deposit')">Déposer · Boîte {{ box+1 }}</button><small v-if="!canRemove">Garde un compagnon apte dans ton équipe.</small><small v-else-if="boxCount(box)>=state.boxSize">Cette boîte est pleine. Choisis-en une autre.</small></template><template v-else><button v-if="state.team.length<6" class="pc-primary" data-pc-withdraw :disabled="busy" @click="send('withdraw')">Ajouter à l’équipe</button><label class="pc-swap-label">{{ state.team.length>=6?'Équipe complète : remplacer un compagnon':'Ou échanger avec un compagnon' }}<select v-model="swapUuid" aria-label="Compagnon à échanger" :disabled="busy"><option value="">Choisir dans ton équipe…</option><option v-for="p in state.team" :key="p.uuid" :value="p.uuid">{{ p.name }} · Niv. {{ p.level }}</option></select></label><button class="pc-primary" data-pc-swap :disabled="busy || !swapUuid" @click="send('swap')">Échanger</button></template><button class="pc-release" data-pc-release :disabled="busy || (source==='team' && !canRemove)" @click="askRelease">Relâcher ce Pokémon</button></div>
          </template><div v-else class="pc-idle"><svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="7" y="9" width="50" height="35" rx="4"/><path d="M25 44v9m14-9v9M18 55h28"/><circle cx="32" cy="26" r="9"/><path d="M23 26h6m6 0h6"/><circle cx="32" cy="26" r="3"/></svg><h3>Une place pour chacun</h3><p>Les nouvelles captures rejoignent le PC quand tes six places sont occupées.</p><small>PV, attaques et objets sont conservés. Pour soigner, parle à l’infirmière.</small></div>
        </aside>
      </div>
      <transition name="pc-loading"><div v-if="opening" class="pc-loading" data-pc-loading role="status" aria-live="polite" @pointerdown.stop.prevent @pointerup.stop.prevent @click.stop.prevent>
        <svg class="pc-loading-screen" viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="8" y="8" width="48" height="34" rx="4"/><path d="M24 42v10m16-10v10M19 53h26M16 34h32"/><path class="pc-loading-signal" d="m22 21 6 5-6 5m12 0h8"/></svg>
        <span>Ouverture du PC…</span><span class="pc-loading-track" aria-hidden="true"><i></i></span>
      </div></transition>
      <footer class="pc-footer"><span>{{ state.count }} / {{ state.capacity }} places occupées</span><span>{{ state.expedition?'Boîtes réservées à cette expédition.':'Stockage sauvegardé avec ton aventure.' }}</span></footer>
      <div v-if="confirmRelease && selected" class="pc-confirm-backdrop"><section ref="confirm" class="pc-confirm" role="alertdialog" aria-modal="true" aria-labelledby="pc-release-title"><pokemon-portrait :src="sprite(selected)"/><h3 id="pc-release-title">Relâcher {{ selected.name }} ?</h3><p>Ce Pokémon quittera définitivement ton aventure{{ state.expedition?' dans cette expédition':'' }}.</p><p v-if="selected.heldItem">Son objet tenu sera rendu au sac.</p><div><button ref="cancelRelease" :disabled="busy" @click="cancelRelease">Garder {{ selected.name }}</button><button class="pc-danger" data-pc-confirm-release :disabled="busy" @click="send('release')">Relâcher définitivement</button></div></section></div>
    </section>
  </div>
  <div v-if="drag" class="pc-drag-ghost" :style="{left:drag.x+'px',top:drag.y+'px'}" aria-hidden="true" data-pc-drag-ghost><pokemon-portrait :src="sprite(drag.pokemon)"/><span>{{ drag.pokemon.name }}</span></div>
  <pokemon-details v-if="detailOpen && detailPokemon" :pokemon="detailPokemon" :position="detailIndex+1" :total="detailList.length" :read-only="true" :moves-order-allowed="!opening && !detailPokemon.isEgg" :moves-order-busy="busy" :moves-order-error="error" :moves-order-notice="notice" :context-label="detailContext" :footer-label="detailContext" @reorder-moves="$emit('command',{action:'reorderMoves',...$event})" @close="closeDetail" @navigate="navigateDetail"/>
  </div>
</template>
<script>
import {waitForBattleAssets,entranceDelay} from '@/services/battleEntrance';
import {createComputerDrag} from '@/services/computerDrag';
import PokemonDetails from './PokemonDetails.vue';
import {computerPokemonDetails} from '@/services/pokemonComputer';
import PokemonPortrait from '../PokemonPortrait.vue';
import ComputerPokemonPortrait from './ComputerPokemonPortrait.vue';
import PotentialStar from '../PotentialStar.vue';
import {localizeTypeName} from '@/services/pokemonTypes';
import {localizeMoveName,localizeAbilityName} from '@/services/i18n';
export default {
  name:'PokemonComputer',components:{PokemonPortrait,PotentialStar,PokemonDetails,ComputerPokemonPortrait},
  props:{state:{type:Object,required:true},busy:Boolean,animationsEnabled:{type:Boolean,default:true},error:String,notice:String,username:String,itemNames:{type:Object,default:()=>({})}},
  data(){return {opening:true,drag:null,detailOpen:false,box:0,uuid:null,source:null,swapUuid:'',confirmRelease:false,previousFocus:null};},
  computed:{
    detailList(){return this.source==='team'?this.state.team:this.state.entries.filter(e=>e.box===this.box).sort((a,b)=>a.slot-b.slot).map(e=>e.pokemon);},
    detailIndex(){return this.detailList.findIndex(p=>p.uuid===this.uuid);},
    detailPokemon(){return computerPokemonDetails(this.selected);},
    detailContext(){return this.source==='team'?'PC · TON ÉQUIPE':`PC · BOÎTE ${this.box+1}`;},
    slots(){return Array.from({length:this.state.boxSize},(_,slot)=>this.state.entries.find(e=>e.box===this.box && e.slot===slot)||null);},
    selected(){return this.source==='team'?this.state.team.find(p=>p.uuid===this.uuid):this.state.entries.find(e=>e.pokemon.uuid===this.uuid)?.pokemon;},
    canRemove(){return this.state.team.length>1 && this.state.team.some(p=>p.uuid!==this.uuid && p.currentHp>0);}
  },
  watch:{busy(value){if(value)this.cancelDrag();},state(){this.cancelDrag();if(!this.selected){const stored=this.state.entries.find(e=>e.pokemon.uuid===this.uuid);if(stored){this.source='box';this.box=stored.box;}else if(this.state.team.some(p=>p.uuid===this.uuid))this.source='team';else{this.uuid=null;this.source=null;this.detailOpen=false;}this.confirmRelease=false;}if(!this.state.team.some(p=>p.uuid===this.swapUuid))this.swapUuid='';}},
  mounted(){this._dragController=createComputerDrag({root:this.$refs.dialog,changed:drag=>{this.drag=drag;},drop:this.dropPokemon,navigateBox:step=>this.changeBox((this.box+step+this.state.boxCount)%this.state.boxCount),ended:()=>{this._suppressClickUntil=performance.now()+500;}});window.addEventListener('blur',this.cancelDrag);document.addEventListener('visibilitychange',this.dragVisibility);this.previousFocus=document.activeElement;this.$refs.close.focus({preventScroll:true});this.prepareOpening();},
  beforeDestroy(){this._openingController?.abort();this._openingController=null;this.cancelDrag();window.removeEventListener('blur',this.cancelDrag);document.removeEventListener('visibilitychange',this.dragVisibility);const previous=this.previousFocus;this.$nextTick(()=>{const target=previous?.isConnected && previous!==document.body?previous:document.querySelector('.mobile-action-a, .menu-toggle-btn');target?.focus({preventScroll:true});});},
  methods:{
    async prepareOpening(){
      this._openingController?.abort();
      const controller=new AbortController(),{signal}=controller,started=performance.now();
      this._openingController=controller;
      this.opening=true;
      await this.$nextTick();
      if(document.hidden || signal.aborted)return;
      await waitForBattleAssets(()=>[...this.$refs.dialog.querySelectorAll('.pc-body .pokemon-portrait img')],{signal});
      if(signal.aborted || this._openingController!==controller)return;
      await this.$nextTick();
      if(this.animationsEnabled && !window.matchMedia('(prefers-reduced-motion: reduce)').matches)await entranceDelay(260-(performance.now()-started),signal);
      if(signal.aborted || this._openingController!==controller)return;
      this.opening=false;
      this._openingController=null;
    },
    startDrag(e,p,from){if(!this.opening && !this.busy && !this.confirmRelease && !this.detailOpen)this._dragController.start(e,p,from);},
    dragMove(e){this._dragController?.move(e);},dragFinish(e){this._dragController?.finish(e);},dragLeave(){this._dragController?.leave();},
    dragCaptureLost(e){if(e.target===this.$refs.dialog)this.cancelDrag();},
    cancelDrag(){this._dragController?.cancel();},dragVisibility(){if(document.hidden){this.cancelDrag();this._openingController?.abort();}else if(this.opening)this.prepareOpening();},
    dropTarget(kind,index){return this.drag?.to?.kind===kind && (kind==='team'?this.drag.to.index===index:this.drag.to.box===this.box && this.drag.to.slot===index);},
    dropPokemon(payload){if(this.busy || payload.to.uuid===payload.pokemonUuid)return;this.uuid=payload.pokemonUuid;this.source=payload.from.kind;this.$emit('command',payload);},
    openDetail(){this.cancelDrag();if(!this.busy)this.detailOpen=true;},
    closeDetail(){this.detailOpen=false;this.$nextTick(()=>this.$refs.detailButton?.focus({preventScroll:true}));},
    navigateDetail(delta){const next=this.detailList[this.detailIndex+delta];if(next)this.uuid=next.uuid;},
    typeName:localizeTypeName,moveName(m){return localizeMoveName(m,'fr');},abilityName(a){return localizeAbilityName(a,'fr');},
    sprite(p){return `${process.env.BASE_URL}img/pokemon/front/${p.pokemonId}.png`;},
    itemName(key){return key?this.itemNames[key] || key.replace(/_/g,' '):'Aucun';},
    boxCount(box){return this.state.entries.filter(e=>e.box===box).length;},
    select(p,source){if(performance.now()<(this._suppressClickUntil||0))return;this.uuid=p.uuid;this.source=source;this.swapUuid='';this.confirmRelease=false;this.$nextTick(()=>{if(window.matchMedia('(max-width:750px)').matches)this.$refs.details?.scrollIntoView({block:'start',behavior:'instant'});});},
    changeBox(box){this.box=box;if(this.source==='box'){this.uuid=null;this.source=null;}this.confirmRelease=false;},
    send(action){this.$emit('command',{action,pokemonUuid:this.uuid,source:this.source,box:this.box,teamUuid:this.swapUuid,confirm:action==='release'});this.confirmRelease=false;},
    askRelease(){this.cancelDrag();this.confirmRelease=true;this.$nextTick(()=>this.$refs.cancelRelease.focus());},
    cancelRelease(){this.confirmRelease=false;this.$nextTick(()=>this.$refs.dialog.querySelector('[data-pc-release]')?.focus());},
    close(){this.cancelDrag();if(!this.busy)this.$emit('close');},
    keydown(e){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();if(this.drag)this.cancelDrag();else if(this.confirmRelease)this.cancelRelease();else this.close();return;}if(e.key!=='Tab')return;const root=this.$refs.confirm || this.$refs.dialog,nodes=[...root.querySelectorAll('button:not(:disabled),select:not(:disabled),[tabindex="0"]')].filter(n=>n.getClientRects().length && !n.closest('[inert]') && getComputedStyle(n).visibility!=='hidden'),first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey && document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey && document.activeElement===last){e.preventDefault();first?.focus();}}
  }
};
</script>
<style scoped>
.pc-body.is-pc-loading{visibility:hidden}
.pc-loading{position:absolute;inset:0;z-index:2;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;padding:60px 24px;background:var(--journal-paper);color:var(--journal-accent);font:600 14px var(--journal-font);cursor:progress}
.pc-loading-screen{width:64px;height:64px;color:var(--journal-accent)}
.pc-loading-track{display:block;overflow:hidden;width:108px;height:3px;border-radius:2px;background:var(--journal-border)}
.pc-loading-track i{display:block;width:40%;height:100%;background:var(--journal-accent);animation:pc-connect 1s ease-in-out infinite alternate}
.pc-loading-leave-active{transition:opacity .18s ease}
.pc-loading-leave-to{opacity:0}
.pc-terminal .pc-close{position:relative;z-index:3}
@keyframes pc-connect{from{transform:translateX(-100%)}to{transform:translateX(250%)}}
.pc-opening-still .pc-loading-track i{animation:none;transform:translateX(75%)}
.pc-opening-still .pc-loading-leave-active{transition:none}
@media(prefers-reduced-motion:reduce){.pc-loading-track i{animation:none;transform:translateX(75%)}.pc-loading-leave-active{transition:none}}

.pc-actions .pc-show-details{background:var(--journal-soft);color:var(--journal-accent);border-color:var(--journal-progress);font-weight:600}

